\label{def:CanonicalColoring}
  The canonical coloring of the action of $G$ is the function 
  \begin{equation*}
    \mathcal{C}_G: \mathbb{N}^n \rightarrow G
  \end{equation*}
  given by taking $x^I$ to the unique $g \in G$ such that 
  $$ \operatorname{Span}(x^I) \simeq \chi(g) \in \operatorname{Irr}(G)$$

\label{def:Nets}
    Let $Y \subset \mathbb{N}^n$ be a diagram and $e_1 = (1,0), e_2 = (0,1)$. For 
    $p \in Y$ the subset
    \begin{equation*}
      H(p) = \{p + n e_i \in Y \mid n \in \mathbb{N}\}
    \end{equation*}
    will be called the hook of $p$, and the subset
    \begin{equation*}
        N(p) = \{p + v \in Y \mid v \in \mathbb{N}^2\}
    \end{equation*}
    will be called its net. $p$ will be referred to as the eye of either its 
    hook or its net.

\label{def:Border}
  The border of $Y$ is the subset 
  \begin{equation*}
    B(Y) = \{p \in Y \mid p + (1,1) \notin Y\}
\end{equation*}
$d(Y) := \# B$ will be called the diameter of Y and the length of the border.

\label{def:CoreTypes}
  Y is...
  \begin{itemize}
    \item an $n$-core if the associated partition is an $n$-core partition
    \item a B-core if Y contains no excisable border strips 
    \item a G-core if $t(Y) = 0$
    \item an MS-core if $T(M) = \emptyset$
  \end{itemize}

\label{CoreEq_nCore}
  $B \rightarrow n$ for the $A_{n-1}$ action.
  \begin{proof}
    Every length $n$ border strip for the $A_{n - 1}$ action is excisable
    by Propositions \ref{ExcisableSubsets} and \ref{RegColoring}. As 
    such the claim follows directly from the discussion in examples c and d 
    on pages 12-13 of \cite{Macdonald_2023}.
  \end{proof}
